package com.medflow.emergency;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;
import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import static org.springframework.http.HttpStatus.*;
@RestController @RequestMapping("/api/emergency") public class EmergencyController {
 private final Access access;public EmergencyController(Access access){this.access=access;}
 public record Request(@NotBlank @Size(max=200)String location,@NotBlank @Size(max=500)String summary){}
 public record Update(@NotBlank @Pattern(regexp="ASSIGNED|IN_PROGRESS|CLOSED")String status,@NotBlank @Pattern(regexp="ADMIN_STANDARD|ADMIN_URGENT")String administrativePriority,boolean assignToSelf){}
 @PostMapping @ResponseStatus(CREATED) @Transactional public Map<String,Object> create(@Valid @RequestBody Request r,Authentication a){access.roles(a,"PATIENT","EMERGENCY_STAFF","ADMIN");UUID id=UUID.randomUUID();access.db.update("INSERT INTO emergency_requests(id,owner_user_id,location,summary,status,administrative_priority) VALUES(?,?,?,?,?,?)",id,access.subject(a),r.location(),r.summary(),"NEW","ADMIN_STANDARD");event(id,a,"NEW","ADMIN_STANDARD");return detail(id,a);}
 @GetMapping("/me") public List<Map<String,Object>> mine(Authentication a){return access.rows("SELECT * FROM emergency_requests WHERE owner_user_id=? ORDER BY created_at DESC LIMIT 100",access.subject(a));}
 @GetMapping public List<Map<String,Object>> all(Authentication a){access.roles(a,"EMERGENCY_STAFF","ADMIN");return access.rows("SELECT * FROM emergency_requests ORDER BY created_at DESC LIMIT 100");}
 @GetMapping("/{id}") public Map<String,Object> detail(@PathVariable UUID id,Authentication a){var r=access.one("SELECT * FROM emergency_requests WHERE id=?",id);access.owner(a,r.get("ownerUserId"),"EMERGENCY_STAFF","ADMIN");r.put("history",access.rows("SELECT status,administrative_priority,created_at FROM emergency_events WHERE request_id=? ORDER BY created_at",id));r.put("notice","Administrative request only. For a possible medical emergency contact local emergency services immediately. This is not dispatch or clinical triage.");return r;}
 @PutMapping("/{id}") @Transactional public Map<String,Object> update(@PathVariable UUID id,@Valid @RequestBody Update r,Authentication a){access.roles(a,"EMERGENCY_STAFF","ADMIN");var existing=access.one("SELECT * FROM emergency_requests WHERE id=? FOR UPDATE",id);String status=String.valueOf(existing.get("status"));String next=switch(status){case "NEW"->"ASSIGNED";case "ASSIGNED"->"IN_PROGRESS";case "IN_PROGRESS"->"CLOSED";default->"";};if(!next.equals(r.status()))throw new ResponseStatusException(CONFLICT,"Invalid administrative status transition");if(status.equals("NEW")&&!r.assignToSelf())throw new ResponseStatusException(BAD_REQUEST,"Initial assignment must be to the authenticated staff member");if(existing.get("assignedTo")!=null&&!access.subject(a).toString().equals(String.valueOf(existing.get("assignedTo")))&&!access.has(a,"ADMIN"))throw new ResponseStatusException(FORBIDDEN,"Request is assigned to another staff member");access.db.update("UPDATE emergency_requests SET status=?,administrative_priority=?,assigned_to=? WHERE id=?",r.status(),r.administrativePriority(),r.assignToSelf()?access.subject(a):UUID.fromString(String.valueOf(existing.get("assignedTo"))),id);event(id,a,r.status(),r.administrativePriority());return detail(id,a);}
 private void event(UUID id,Authentication a,String status,String priority){access.db.update("INSERT INTO emergency_events(id,request_id,actor_user_id,status,administrative_priority) VALUES(?,?,?,?,?)",UUID.randomUUID(),id,access.subject(a),status,priority);}
}
